CREATE POLICY "HO table configuration within tenant" ON public.pos_tables FOR ALL TO authenticated USING ((public.has_role('ho_admin') OR public.has_role('ho_owner') OR public.has_role('1_HO_Admin') OR public.has_role('1_HO_Owner')) AND EXISTS (SELECT 1 FROM public.branches b WHERE b.id = branch_id AND b.tenant_id = public.current_tenant_id())) WITH CHECK ((public.has_role('ho_admin') OR public.has_role('ho_owner') OR public.has_role('1_HO_Admin') OR public.has_role('1_HO_Owner')) AND EXISTS (SELECT 1 FROM public.branches b WHERE b.id = branch_id AND b.tenant_id = public.current_tenant_id()));
CREATE POLICY "HO section configuration within tenant" ON public.pos_table_sections FOR ALL TO authenticated USING ((public.has_role('ho_admin') OR public.has_role('ho_owner') OR public.has_role('1_HO_Admin') OR public.has_role('1_HO_Owner')) AND EXISTS (SELECT 1 FROM public.branches b WHERE b.id = branch_id AND b.tenant_id = public.current_tenant_id())) WITH CHECK ((public.has_role('ho_admin') OR public.has_role('ho_owner') OR public.has_role('1_HO_Admin') OR public.has_role('1_HO_Owner')) AND EXISTS (SELECT 1 FROM public.branches b WHERE b.id = branch_id AND b.tenant_id = public.current_tenant_id()));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.pos_tables, public.pos_table_sections TO authenticated;
GRANT ALL ON public.pos_tables, public.pos_table_sections TO service_role;